import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { OrderItem } from '../../src/entities/order-item.entity';
import { buildOrderItem } from '../factories/order-item.factory';
import { Order } from '../../src/entities/order.entity';
import { buildOrder } from '../factories/order.factory';

describe('OrderItem Repository', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let orderId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const orderEntity = em.create(
      Order,
      buildOrder(),
    );
    await em.persistAndFlush(orderEntity);
    orderId = orderEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  it('creates and persists an entity', async () => {
    const em = orm.em.fork();
    const data = buildOrderItem({ order: orderId });
    const entity = em.create(OrderItem, data);
    await em.persistAndFlush(entity);
    expect(entity.id).toBeDefined();
  });

  it('retrieves an entity by id', async () => {
    const em = orm.em.fork();
    const data = buildOrderItem({ order: orderId });
    const saved = em.create(OrderItem, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(OrderItem, { id: saved.id });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('returns null for non-existent id', async () => {
    const em = orm.em.fork();
    const found = await em.findOne(OrderItem, {
      id: '00000000-0000-0000-0000-000000000099',
    });
    expect(found).toBeNull();
  });

  it('updates an entity field', async () => {
    const em = orm.em.fork();
    const data = buildOrderItem({ order: orderId });
    const saved = em.create(OrderItem, data);
    await em.persistAndFlush(saved);
    saved.productId = '660e8400-e29b-41d4-a716-446655440001';
    await em.flush();
    const reloaded = await em.findOne(OrderItem, { id: saved.id });
    expect(reloaded).not.toBeNull();
    expect(reloaded!.productId).toEqual(saved.productId);
  });

  it('deletes an entity', async () => {
    const em = orm.em.fork();
    const data = buildOrderItem({ order: orderId });
    const saved = em.create(OrderItem, data);
    await em.persistAndFlush(saved);
    await em.removeAndFlush(saved);
    const found = await em.findOne(OrderItem, { id: saved.id });
    expect(found).toBeNull();
  });

  it('lists all entities', async () => {
    const em = orm.em.fork();
    const data = buildOrderItem({ order: orderId });
    await em.persistAndFlush(em.create(OrderItem, data));
    const all = await em.find(OrderItem, {});
    expect(all.length).toBeGreaterThanOrEqual(1);
  });

  it('persists with order foreign key', async () => {
    const em = orm.em.fork();
    const data = buildOrderItem({ order: orderId });
    const saved = em.create(OrderItem, data);
    await em.persistAndFlush(saved);
    await em.populate(saved, ['order']);
    expect(saved.order.id).toBe(orderId);
  });
});
